mapper.update:
update A1_MFG.DUMMY_MONITOR_DETAIL
set ACTIVE_FLAG = #{activeFlag},STD_F = #{stdf},UPDATE_TIME = sysdate,UPDATE_USER = #{updateUser}
,KEY_COMMENT = #{keyComment}
where FAB = #{fab}
and PURPOSE = #{purpose}

mapper.delete:
delete from A1_MFG.DUMMY_MONITOR_DETAIL
where FAB = #{fab}
and PURPOSE = #{purpose}

mapper.select:
select FAB,MODULE,STD_F,PURPOSE,ACTIVE_FLAG,STD_STOCK,MFG_QTY ,AREA,BANK_ID,USE_EQP,F_COMMENT,KEY_COMMENT ,ALARM_FLAG,UPDATE_USER,UPDATE_TIME ,SPECIAL_STOCK ,ROUND(MFG_QTY - (STD_STOCK *STD_F)) AS STOCK_DIFF ,ROUND(MFG_QTY - SPECIAL_STOCK) AS SPECIAL_STOCK_DIFF from A1_MFG.DUMMY_MONITOR_DETAIL where FAB = #{fab}
and MODULE = #{module}
and PURPOSE like'%'||#{purpose}||'%'

select A.* from A1_MFG.DUMMY_MONITOR_DETAIL A JOIN (
SELECT #{item.fab} FAB,#{item.purpose} PURPOSE FROM DUAL
)B ON A.FAB = B.FAB AND A.PURPOSE = B.PURPOSE
